import type { SynapseEnhancedHttpClient } from "../utils/http.ts";

export class AudioUploadApi {
    public constructor(private httpClient: SynapseEnhancedHttpClient) {}

    public async upload(
        file: File | Blob,
        options?: {
            filename?: string;
            contentType?: string;
        },
    ): Promise<{
        content_uri: string;
    }> {
        const formData = new FormData();
        formData.append("file", file);

        if (options?.filename) {
            formData.append("filename", options.filename);
        }

        if (options?.contentType) {
            formData.append("content_type", options.contentType);
        }

        const response = await this.httpClient.post<{
            content_uri: string;
        }>("/_matrix/client/v1/upload/audio", formData);
        return response.data;
    }
}
